def transform(grid):
    # Fill enclosed regions bounded by non-background frame pixels. ARC demo suggests
    # background holes receive color 7, with small 2x2 hole color 2.
    from collections import deque
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); comp=[]; edge=False
            while q:
                y,x=q.popleft(); comp.append((y,x))
                if y==0 or x==0 or y==h-1 or x==w-1: edge=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
